const data = $input.first().json;

// Telegram message text
const text = String(data.message?.text || "");

function extractField(field) {
  const regex = new RegExp(
    `${field}:\\s*(.*?)(?=\\n|$)`,
    "i"
  );

  const match = text.match(regex);

  return match ? match[1].trim() : "";
}

function extractList(field) {
  const value = extractField(field);

  if (!value) {
    return [];
  }

  return value
    .split(",")
    .map(item => item.trim())
    .filter(item => item.length > 0);
}

const student = {
  name: extractField("Student Name"),

  age: Number(extractField("Age")) || null,

  education: extractField("Education"),

  college: extractField("College"),

  stream: extractField("Stream"),

  subjects: extractList("Subjects"),

  academicGoal: extractField("Academic Goal"),

  dailyStudyTime: extractField("Daily Study Time"),

  preferredStudyTime: extractField("Preferred Study Time"),

  studyStyle: extractField("Study Style"),

  strongSubjects: extractList("Strong Subjects"),

  weakSubjects: extractList("Subjects Needing More Focus"),

  additionalGoals: extractList("Additional Goals")
};

return [
  {
    json: student
  }
];

