const aiOutput = $input.first().json.output;

// Remove markdown code fences if Gemini adds them
const cleanedOutput = aiOutput
  .replace(/^```json\s*/i, '')
  .replace(/^```\s*/i, '')
  .replace(/\s*```$/i, '')
  .trim();

// Convert AI JSON string into a real JavaScript object
let plan;

try {
  plan = JSON.parse(cleanedOutput);
} catch (error) {
  throw new Error(
    "AI Agent did not return valid JSON. Output was: " + aiOutput
  );
}

// Get original student information
const student = $('Code in JavaScript').first().json;

return [
  {
    json: {
      name: student.name,
      age: student.age,
      education: student.education,
      college: student.college,
      stream: student.stream,
      subjects: student.subjects,
      academicGoal: student.academicGoal,
      dailyStudyTime: student.dailyStudyTime,
      preferredStudyTime: student.preferredStudyTime,
      studyStyle: student.studyStyle,
      strongSubjects: student.strongSubjects,
      weakSubjects: student.weakSubjects,
      additionalGoals: student.additionalGoals,

      summary: plan.summary,
      daily_plan: plan.daily_plan,
      weekly_target: plan.weekly_target,
      revision_plan: plan.revision_plan,
      progress_tracking: plan.progress_tracking
    }
  }
];
